import{_ as e,a,b as i}from"./chunks/setup-smartscreen-2.Bm2h4sAv.js";import{_ as r,a as n}from"./chunks/setup-vrchat-osc.OjexboPL.js";import{_ as l,o,c as u,ag as s}from"./chunks/framework.DTisvaUJ.js";const V=JSON.parse('{"title":"はじめかた — VRChatで音声認識・読み上げを使う","description":"MutelinkのインストールからVRChatでの会話までを案内。VB-Audio Virtual Cable、VRChatのマイクとOSC、クイックセットアップの準備を説明します。","frontmatter":{"title":"はじめかた — VRChatで音声認識・読み上げを使う","description":"MutelinkのインストールからVRChatでの会話までを案内。VB-Audio Virtual Cable、VRChatのマイクとOSC、クイックセットアップの準備を説明します。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"はじめかた — VRChatで音声認識・読み上げを使う | Mutelink"}],["meta",{"property":"og:description","content":"MutelinkのインストールからVRChatでの会話までを案内。VB-Audio Virtual Cable、VRChatのマイクとOSC、クイックセットアップの準備を説明します。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"はじめかた — VRChatで音声認識・読み上げを使う | Mutelink"}],["meta",{"name":"twitter:description","content":"MutelinkのインストールからVRChatでの会話までを案内。VB-Audio Virtual Cable、VRChatのマイクとOSC、クイックセットアップの準備を説明します。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/guide/getting-started"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/guide/getting-started"}]]},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),h={name:"guide/getting-started.md"};function p(g,t,d,m,c,b){return o(),u("div",null,[...t[0]||(t[0]=[s('<h1 id="はじめかた" tabindex="-1">はじめかた <a class="header-anchor" href="#はじめかた" aria-label="Permalink to &quot;はじめかた&quot;">​</a></h1><p>インストールから、VRChatで話せるようになるまでの手順です。Mutelinkの中の設定は、初回に開く「クイックセットアップ」が案内します。ここでは、Mutelinkの外で必要な準備を中心に説明します。</p><h2 id="_1-vb-audio-virtual-cableを入れる" tabindex="-1">1. VB-Audio Virtual Cableを入れる <a class="header-anchor" href="#_1-vb-audio-virtual-cableを入れる" aria-label="Permalink to &quot;1. VB-Audio Virtual Cableを入れる&quot;">​</a></h2><p>読み上げた声を、VRChatのマイクに流すための無料のソフトです。チャットボックスだけで使うなら、この手順は飛ばしてください。</p><ol><li><a href="https://vb-audio.com/Cable/" target="_blank" rel="noreferrer">VB-Audio Virtual Cable</a>をダウンロードして、インストールします。</li><li>Windowsのサウンドの設定に「CABLE Input」と「CABLE Output」が出ていることを確認します。出ていないときは、PCを再起動します。</li></ol><p><strong>Mutelinkより先に入れてください。</strong> Mutelinkを開いたまま入れた場合は、Mutelinkを起動し直します。</p><p><img src="'+e+'" alt="Windowsのサウンドの設定に「CABLE Input」と「CABLE Output」が出ている"></p><h2 id="_2-mutelinkをインストールする" tabindex="-1">2. Mutelinkをインストールする <a class="header-anchor" href="#_2-mutelinkをインストールする" aria-label="Permalink to &quot;2. Mutelinkをインストールする&quot;">​</a></h2><ol><li><a href="https://github.com/utyujinn/Mutelink-releases/releases" target="_blank" rel="noreferrer">Releases</a>(または<a href="https://utyujin.booth.pm/items/8914909" target="_blank" rel="noreferrer">BOOTH</a>)から、インストーラー(<code>Mutelink_x.x.x_x64-setup.exe</code>)をダウンロードします。</li><li>実行します。管理者権限は要りません。</li></ol><p>コード署名をしていないため、「WindowsによってPCが保護されました」と表示されることがあります。「詳細情報」を押してから「実行」を押すと進めます。</p><table tabindex="0"><thead><tr><th>①「詳細情報」を押す</th><th>②「実行」を押す</th></tr></thead><tbody><tr><td><img src="'+a+'" alt="「詳細情報」を押す"></td><td><img src="'+i+'" alt="「実行」を押す"></td></tr></tbody></table><h2 id="_3-クイックセットアップを進める" tabindex="-1">3. クイックセットアップを進める <a class="header-anchor" href="#_3-クイックセットアップを進める" aria-label="Permalink to &quot;3. クイックセットアップを進める&quot;">​</a></h2><p>初めて起動すると「クイックセットアップ」が開きます。最初に使い方(声で話す、翻訳する、キーボードで打つ、相手の声を字幕で読む、VRで使う)を選ぶと、それに必要な設定だけが順番に出ます。</p><p>迷いやすいのは、次の3つです。</p><ul><li><strong>マイク</strong>: 実際に話すマイクを選びます。「CABLE Output」は選ばないでください(読み上げた声を認識してしまいます)。</li><li><strong>スピーカー</strong>: 読み上げを使うときは、VRChatに届けるための「CABLE Input」と、自分で聞くためのスピーカーやヘッドホンの両方を選びます。</li><li><strong>音声認識と読み上げの声</strong>: どれを選ぶか迷ったら、<a href="/Mutelink-releases/compare/speech-recognition">音声認識エンジンの比較</a>と<a href="/Mutelink-releases/compare/voices">読み上げの声の聞き比べ</a>を見てください。あとから変えられます。</li></ul><p>クイックセットアップは、設定 &gt; 使い方 からやり直せます。</p><h2 id="_4-vrchat側を設定する" tabindex="-1">4. VRChat側を設定する <a class="header-anchor" href="#_4-vrchat側を設定する" aria-label="Permalink to &quot;4. VRChat側を設定する&quot;">​</a></h2><h3 id="声を流すとき" tabindex="-1">声を流すとき <a class="header-anchor" href="#声を流すとき" aria-label="Permalink to &quot;声を流すとき&quot;">​</a></h3><p>VRChatの 設定 &gt; オーディオ で、マイクを「CABLE Output」にします。</p><div class="warning custom-block"><p class="custom-block-title">「既定(Default)」のままにしないでください</p><p>VRChatのマイクが「既定」のままだと、実際のマイクが使われて、あなたの地声がVRChatに流れることがあります。必ず「CABLE Output」を選んでください。</p></div><p>読み上げの声が途中で切れないように、VRChatのマイクは常にオン(トグルでオンのまま)にしておくことをおすすめします。</p><p><img src="'+r+'" alt="VRChatのマイクを「CABLE Output」にする"></p><h3 id="チャットボックスだけで使うとき" tabindex="-1">チャットボックスだけで使うとき <a class="header-anchor" href="#チャットボックスだけで使うとき" aria-label="Permalink to &quot;チャットボックスだけで使うとき&quot;">​</a></h3><p>VRChatのマイクをミュートにします。ミュートにしないと、音声認識のために話した声が、そのまま相手に聞こえます。</p><h3 id="チャットボックスを使うとき" tabindex="-1">チャットボックスを使うとき <a class="header-anchor" href="#チャットボックスを使うとき" aria-label="Permalink to &quot;チャットボックスを使うとき&quot;">​</a></h3><p>VRChatのOSCを有効にします(リングメニュー &gt; Options &gt; OSC &gt; Enabled)。</p><p><img src="'+n+'" alt="VRChatのOSCを「Enabled」にする"></p><h2 id="_5-使ってみる" tabindex="-1">5. 使ってみる <a class="header-anchor" href="#_5-使ってみる" aria-label="Permalink to &quot;5. 使ってみる&quot;">​</a></h2><p>メイン画面で音声認識をオンにして、マイクに向かって話します。認識された文章が画面に出るので、送信します(自動で送る設定にもできます)。</p><p>各ボタンや設定の意味は、設定画面の右上の「？」を押すと、その場に説明が出ます。</p><p>うまく動かないときは、<a href="/Mutelink-releases/help/troubleshooting">困ったときの対処</a>を見てください。</p>',31)])])}const f=l(h,[["render",p]]);export{V as __pageData,f as default};
